package me.tewodros.dael.audio

import android.content.Context
import android.media.AudioAttributes
import android.media.MediaPlayer
import android.os.Handler
import android.os.Looper
import android.speech.tts.TextToSpeech
import android.speech.tts.UtteranceProgressListener
import android.speech.tts.Voice
import androidx.compose.runtime.staticCompositionLocalOf
import java.io.File
import java.util.Locale

/**
 * Says a phrase. Prefers a bundled natural-voice clip (generated by tools/gen_voices.py and
 * looked up by a slug of the exact text); falls back to the system text-to-speech engine.
 */
class Speaker(context: Context) {
    private val app = context.applicationContext
    private var ready = false
    private lateinit var tts: TextToSpeech
    private var player: MediaPlayer? = null
    private val mainHandler = Handler(Looper.getMainLooper())

    init {
        tts = TextToSpeech(app) { status ->
            ready = status == TextToSpeech.SUCCESS
            if (ready) {
                tts.language = Locale.getDefault()
                tts.setSpeechRate(0.9f)
                pickBestVoice()
            }
        }
    }

    /** Chooses the highest quality offline voice available, which beats the default on most phones. */
    private fun pickBestVoice() {
        val lang = Locale.getDefault().language
        val best = runCatching { tts.voices }.getOrNull()
            ?.filter { it.locale.language == lang && !it.isNetworkConnectionRequired && !it.features.contains(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED) }
            ?.maxByOrNull { it.quality * 10 + if (it.name.contains("female", true)) 1 else 0 }
        if (best != null && best.quality >= Voice.QUALITY_HIGH) tts.voice = best
    }

    fun say(text: String, interrupt: Boolean = true, onDone: (() -> Unit)? = null) {
        val resId = app.resources.getIdentifier(slug(text), "raw", app.packageName)
        if (resId != 0) {
            playRaw(resId, interrupt, onDone)
            return
        }
        if (!ready) { onDone?.invoke(); return }
        // Fallback: synthesize to a file and play it through MediaPlayer so it follows the same
        // speaker routing as every other sound. Direct TTS playback cannot be routed and would
        // come out of connected earbuds.
        if (interrupt) stop()
        val file = File(app.cacheDir, "tts_${slug(text)}.wav")
        if (file.exists() && file.length() > 0) { playFile(file, onDone); return }
        val id = text.hashCode().toString()
        tts.setOnUtteranceProgressListener(object : UtteranceProgressListener() {
            override fun onStart(utteranceId: String?) {}
            override fun onError(utteranceId: String?) { if (utteranceId == id) mainHandler.post { onDone?.invoke() } }
            override fun onDone(utteranceId: String?) { if (utteranceId == id) mainHandler.post { playFile(file, onDone) } }
        })
        tts.synthesizeToFile(text, null, file, id)
    }

    private fun playFile(file: File, onDone: (() -> Unit)?) {
        val mp = MediaPlayer()
        runCatching {
            mp.setAudioAttributes(attrs)
            mp.setDataSource(file.absolutePath)
            mp.prepare()
        }.onFailure { mp.release(); onDone?.invoke(); return }
        startPlayer(mp, onDone)
    }

    /** Plays a bundled sound effect such as a real animal recording (res/raw/s_<key>.ogg). */
    fun sound(key: String, interrupt: Boolean = true, onDone: (() -> Unit)? = null) {
        val resId = app.resources.getIdentifier("s_$key", "raw", app.packageName)
        if (resId == 0) { onDone?.invoke(); return }
        playRaw(resId, interrupt, onDone)
    }

    /** Says a name, then plays its sound, then runs [onDone]. Used by the animal game and pretend calls. */
    fun sayThenSound(text: String, soundKey: String, onDone: (() -> Unit)? = null) {
        say(text) { sound(soundKey, interrupt = false, onDone = onDone) }
    }

    private val attrs = AudioAttributes.Builder()
        .setUsage(AudioAttributes.USAGE_MEDIA)
        .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
        .build()

    private fun playRaw(resId: Int, interrupt: Boolean, onDone: (() -> Unit)?) {
        if (interrupt) stop()
        // Build the player by hand so the preferred output device is set before prepare().
        val mp = MediaPlayer()
        runCatching {
            mp.setAudioAttributes(attrs)
            AudioRoute.apply(app, mp)
            app.resources.openRawResourceFd(resId).use { fd -> mp.setDataSource(fd.fileDescriptor, fd.startOffset, fd.length) }
            mp.prepare()
        }.onFailure { mp.release(); onDone?.invoke(); return }
        startPlayer(mp, onDone)
    }

    private fun startPlayer(mp: MediaPlayer, onDone: (() -> Unit)?) {
        player = mp
        AudioRoute.apply(app, mp)
        mp.setOnCompletionListener {
            it.release()
            if (player === it) player = null
            onDone?.invoke()
        }
        mp.start()
    }

    fun stop() {
        player?.let { runCatching { it.stop(); it.release() } }
        player = null
        if (ready) tts.stop()
    }

    fun shutdown() {
        stop()
        tts.shutdown()
    }

    companion object {
        /** Must match slug() in tools/gen_voices.py. */
        fun slug(text: String): String {
            val s = text.lowercase().replace(Regex("[^a-z0-9]+"), "_").trim('_')
            return "v_" + s.take(60).trimEnd('_')
        }
    }
}

val LocalSpeaker = staticCompositionLocalOf<Speaker> { error("Speaker not provided") }
